INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(11193246, 'Lunalight Reincarnation Dance', '月光轮回舞蹈', '月光輪廻舞踊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「月光轮回舞踊」在1回合只能发动1张。 ①：自己场上的怪兽被战斗·效果破坏的场合才能发动。从卡组把最多2只「月光」怪兽加入手卡。'),
(88753594, 'Lunalight Sabre Dancer', '月光舞剑虎姬', '月光舞剣虎姫', 'Fusion Monster', 'Beast-Warrior', 'DARK', 9, 3000, 2600, '「月光」怪兽×3 这张卡不用融合召唤不能特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升双方墓地的兽战士族怪兽以及除外中的兽战士族怪兽数量×200。 ②：这张卡不会成为对方的效果的对象。 ③：把墓地的这张卡除外，以自己场上1只融合怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升3000。这个效果在这张卡送去墓地的回合不能发动。'),
(13935001, 'Lunalight Serenade Dance', '月光小夜曲舞蹈', '月光小夜曲舞踊', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有融合怪兽融合召唤时，以那之内的1只为对象才能发动。以下效果适用。 ●在对方场上把1只「月光衍生物」（兽战士族·暗·4星·攻/守2000）特殊召唤。 ●作为对象的怪兽的攻击力上升对方场上的怪兽数量×500。 ②：自己主要阶段，把墓地的这张卡除外才能发动。选自己1张手卡送去墓地，从卡组把1只「月光」怪兽特殊召唤。'),
(35763582, 'Lunalight Silver Hound', '月光银狗', '月光銀狗', 'Effect Monster', 'Beast-Warrior', 'DARK', 3, 1400, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被效果送去墓地的场合才能发动。从卡组把「月光银狗」以外的1只「月光」怪兽特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不是「月光」怪兽不能从额外卡组特殊召唤。 ②：魔法·陷阱卡的效果在场上发动时，从自己墓地把这张卡和1只「月光」融合怪兽除外才能发动。那个发动无效。'),
(83190280, 'Lunalight Tiger', '月光虎', '月光虎', 'Pendulum Effect Monster', 'Beast-Warrior', 'LIGHT', 3, 1200, 800, '这个卡名的怪兽效果1回合只能使用1次。 ①：场上的这张卡被战斗·效果破坏的场合，以自己墓地1只「月光」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(84812868, 'Lunalight White Rabbit', '月光白兔', '月光白兎', 'Effect Monster', 'Beast-Warrior', 'DARK', 2, 800, 800, '①：这张卡召唤成功时，以「月光白兔」以外的自己墓地1只「月光」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：1回合1次，以最多有这张卡以外的自己场上的「月光」卡数量的对方场上的魔法·陷阱卡为对象才能发动。那些卡回到持有者手卡。'),
(47705572, 'Lunalight Wolf', '月光狼', '月光狼', 'Pendulum Effect Monster', 'Beast-Warrior', 'LIGHT', 6, 2000, 1800, '①：只要这张卡在怪兽区域存在，自己的「月光」怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(50546208, 'Lunalight Yellow Marten', '月光黄鼬', '月光黄鼬', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 800, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，以「月光黄鼬」以外的自己场上1张「月光」卡为对象才能发动。那张卡回到手卡，这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡被效果送去墓地的场合才能发动。从卡组把1张「月光」魔法·陷阱卡加入手卡。'),
(62210247, 'Lunar Queen Elzaim', '月之女神 艾露塞姆', '月の女神 エルザェム', 'Normal Monster', 'Fairy', 'LIGHT', 3, 750, 1100, '守护月亮的美丽女神。使用月光屏障守备攻击。'),
(11091375, 'Luster Dragon', '蓝玉石龙', 'サファイアドラゴン', 'Normal Monster', 'Dragon', 'WIND', 4, 1900, 1600, '全身被蓝宝石覆盖，样子非常美丽的龙。虽然并不喜欢斗争，却具备很高攻击力。'),
(17658803, 'Luster Dragon #2', '翠玉石龙', 'エメラルド・ドラゴン', 'Normal Monster', 'Dragon', 'WIND', 6, 2400, 1400, '吞食翡翠的龙。被其美态吸引住并丢掉性命的人不计其数。'),
(92746535, 'Luster Pendulum, the Dracoslayer', '龙剑士 光栅行者 灵摆', '竜剣士ラスターP', 'Pendulum Tuner Effect Monster', 'Dragon', 'LIGHT', 4, 1850, NULL, '不能用这张卡为素材把「龙剑士」怪兽以外的融合·同调·超量怪兽特殊召唤。'),
(84385264, 'Lycanthrope', '合成狼人', 'ライカン・スロープ', 'Ritual Effect Monster', 'Beast-Warrior', 'EARTH', 6, 2400, 1800, '用「合成魔术」降临。这张卡给与对方基本分战斗伤害时，给与对方基本分自己墓地存在的通常怪兽数量×200的数值的伤害。'),
(81916745, 'Lycoris Lilyreaper', '石蒜百合收割者', NULL, 'Synchro Monster', 'Plant', 'DARK', 5, 800, 2400, '调整+调整以外的怪兽1只以上 这张卡在自己怪兽区域存在的状态，怪兽从场上被送去对方墓地的场合（伤害步骤也能发动）：自己回复对方墓地的那之内1只怪兽的攻击力数值的基本分。 这张卡在自己墓地存在的状态，对方受到效果伤害的场合（伤害步骤除外）：可以把这张卡除外；持有自己和对方的基本分相差数值以下的攻击力的场上1只怪兽送去墓地。 「石蒜百合收割者」的每个效果1回合只能使用1次。'),
(22624373, 'Lyla, Lightsworn Sorceress', '光道魔术师 莱拉', 'ライトロード・マジシャン ライラ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1700, 200, '①：以对方场上1张魔法·陷阱卡为对象才能发动。自己场上的表侧攻击表示的这张卡变成守备表示，作为对象的对方的卡破坏。这个效果的发动后，直到下次的自己回合的结束时这张卡不能把表示形式变更。 ②：自己结束阶段发动。从自己卡组上面把3张卡送去墓地。'),
(10071151, 'Lyla, Twilightsworn Enchantress', '暮光道巫师 丽拉', 'トワイライトロード・ソーサラー ライラ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1700, 200, '①：1回合1次，魔法·陷阱卡的效果发动时，从自己的手卡·墓地把1只「光道」怪兽除外，以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：1回合1次，这张卡以外的自己的「光道」怪兽的效果发动的场合发动。从自己卡组上面把3张卡送去墓地。'),
(73318863, 'Lyna the Light Charmer', '光灵使 莱娜', '光霊使いライナ', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 3, 500, 1500, '①：这张卡反转的场合，以对方场上1只光属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到那只怪兽的控制权。'),
(9839945, 'Lyna the Light Charmer, Lustrous', '照耀之光灵使 莱娜', '照耀の光霊使いライナ', 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 1850, NULL, '包含光属性怪兽的怪兽2只 这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：以对方墓地1只光属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的光属性怪兽加入手卡。'),
(48608796, 'Lyrilusc - Assembled Nightingale', '抒情歌鸲－聚合夜莺', 'LL－アセンブリー・ナイチンゲール', 'XYZ Monster', 'Winged Beast', 'WIND', 1, NULL, NULL, '1星怪兽×2只以上 ①：这张卡的攻击力上升这张卡的超量素材数量×200。 ②：这张卡可以直接攻击，持有超量素材的这张卡在同1次的战斗阶段中可以作出最多有那个数量的攻击。 ③：1回合1次，把这张卡1个超量素材取除才能发动。直到回合结束时，自己场上的「抒情歌鸲」怪兽不会被战斗·效果破坏，自己受到的战斗伤害变成0。这个效果在对方回合也能发动。'),
(10182251, 'Lyrilusc - Beryl Canary', '抒情歌鸲－绿柱金丝雀', 'LL－ベリル・カナリー', 'Effect Monster', 'Winged Beast', 'WIND', 1, NULL, 200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以自己墓地1只「抒情歌鸲」怪兽为对象才能发动。这张卡和作为对象的怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：场上的这张卡为素材作超量召唤的风属性怪兽得到以下效果。 ●这张卡的攻击力上升200，不能把控制权变更。'),
(45354718, 'Lyrilusc - Bird Call', '抒情歌鸲－鸟哨', 'LL－バード・コール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组选1只「抒情歌鸲」怪兽加入手卡或送去墓地。那之后，可以把和那只怪兽卡名不同的1只「抒情歌鸲」怪兽从手卡特殊召唤。'),
(72859417, 'Lyrilusc - Bird Sanctuary', '抒情歌鸲－鸟禁猎区', 'LL－バード・サンクチュアリ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上2只鸟兽族超量怪兽为对象才能发动。作为对象的怪兽之内1只在另1只怪兽下面重叠作为超量素材（把持有超量素材的怪兽重叠的场合那些超量素材也全部重叠）。 ②：持有超量素材3个以上的超量怪兽在自己场上存在的场合才能发动。自己从卡组抽1张。'),
(56619778, 'Lyrilusc - Bird Strike', '抒情歌鸲－鸟击', 'LL－バード・ストライク', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「抒情歌鸲」怪兽存在的场合才能发动。对方场上的全部表侧表示怪兽的效果直到回合结束时无效化。'),
(46576366, 'Lyrilusc - Celestine Wagtail', '抒情歌鸲－天青白鹡鸰', 'LL－セレスト・ワグテイル', 'Effect Monster', 'Winged Beast', 'WIND', 1, 200, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从卡组把1张「抒情歌鸲」魔法·陷阱卡加入手卡。 ②：这张卡在墓地存在的场合，以自己场上1只「抒情歌鸲」超量怪兽为对象才能发动。把这张卡在那只怪兽下面重叠作为超量素材。'),
(34550857, 'Lyrilusc - Cobalt Sparrow', '抒情歌鸲－钴尖晶雀', 'LL－コバルト・スパロー', 'Effect Monster', 'Winged Beast', 'WIND', 1, NULL, 100, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从卡组把1只鸟兽族·1星怪兽加入手卡。 ②：场上的这张卡为素材作超量召唤的风属性怪兽得到以下效果。 ●这张卡不会成为对方的效果的对象。'),
(72971064, 'Lyrilusc - Ensemblue Robin', '抒情歌鸲－合唱蓝姬鹟', 'LL－アンサンブルー・ロビン', 'XYZ Monster', 'Winged Beast', 'WIND', 1, NULL, NULL, '1星怪兽×2只以上 ①：这张卡的攻击力上升这张卡的超量素材数量×500。 ②：对方对怪兽的特殊召唤成功的场合，把这张卡1个超量素材取除，以那1只特殊召唤的怪兽为对象才能发动。那只怪兽回到持有者手卡。 ③：这张卡被对方送去墓地的场合，以这张卡以外的自己墓地1只「抒情歌鸲」怪兽为对象才能发动。那只怪兽加入手卡。'),
(76815942, 'Lyrilusc - Independent Nightingale', '抒情歌鸲－独行夜莺', 'LL－インディペンデント・ナイチンゲール', 'Fusion Monster', 'Winged Beast', 'WIND', 1, 1000, NULL, '「抒情歌鸲-聚集夜莺」＋「抒情歌鸲」怪兽 ①：原本卡名包含「抒情歌鸲」的超量怪兽作为素材让这张卡融合召唤成功的场合才能发动。这张卡的等级上升那些怪兽持有的超量素材数量的数值。 ②：这张卡的攻击力上升这张卡的等级×500，这张卡不受其他卡的效果影响。 ③：1回合1次，自己主要阶段才能发动。给与对方这张卡的等级×500伤害。'),
(8243121, 'Lyrilusc - Phantom Feathers', '抒情歌鸲－比翼丽鸟', 'LL－比翼の麗鳥', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「抒情歌鸲」怪兽为对象才能发动。对方场上的全部怪兽的攻击力变成和作为对象的怪兽的攻击力相同，对方场上的全部怪兽的等级·阶级变成1。 ②：对方怪兽向自己的「抒情歌鸲」怪兽攻击宣言时，把墓地的这张卡除外才能发动。那只自己怪兽的攻击力直到回合结束时变成和那只对方怪兽的攻击力相同。'),
(19369609, 'Lyrilusc - Promenade Thrush', '抒情歌鸲－逍遥音乐鸫', 'LL－プロム・スラッシュ', 'XYZ Monster', 'Winged Beast', 'WIND', 1, NULL, NULL, '1星怪兽×2只以上 ①：这张卡的攻击力上升这张卡的超量素材数量×500。 ②：1回合1次，把这张卡1个超量素材取除，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡回到持有者卡组。 ③：这张卡以外的自己怪兽进行战斗的伤害步骤开始时，把这张卡的超量素材任意数量取除才能发动。那只自己怪兽的攻击力直到回合结束时上升取除数量×300。'),
(8491961, 'Lyrilusc - Recital Starling', '抒情歌鸲－独唱星椋', 'LL－リサイト・スターリング', 'XYZ Monster', 'Winged Beast', 'WIND', 1, NULL, NULL, '1星怪兽×2只以上 ①：这张卡超量召唤成功的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力上升这张卡的超量素材数量×300。 ②：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1只鸟兽族·1星怪兽加入手卡。 ③：超量召唤的这张卡的战斗发生的对自己的战斗伤害让对方也承受。'),
(60954556, 'Lyrilusc - Sapphire Swallow', '抒情歌鸲－蓝宝燕', 'LL－サファイア・スワロー', 'Effect Monster', 'Winged Beast', 'WIND', 1, 100, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有鸟兽族怪兽存在的场合才能发动。这张卡和1只鸟兽族·1星怪兽从手卡特殊召唤。 ②：场上的这张卡为素材作超量召唤的风属性怪兽得到以下效果。 ●这次超量召唤成功的场合，以自己墓地1只「抒情歌鸲」怪兽为对象才能发动。那只怪兽在这张卡下面重叠作为超量素材。'),
(97949165, 'Lyrilusc - Turquoise Warbler', '抒情歌鸲－绿松莺', 'LL－ターコイズ・ワーブラー', 'Effect Monster', 'Winged Beast', 'WIND', 1, 100, 100, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合才能发动。从自己的手卡·墓地选1只「抒情歌鸲」怪兽特殊召唤。'),
(56342351, 'M-Warrior #1', '磁体战士１号', 'マグネッツ１号', 'Normal Monster', 'Warrior', 'EARTH', 3, 1000, 500, '擅长配合的战士，发动强大的磁力，谁也逃不掉。'),
(92731455, 'M-Warrior #2', '磁体战士２号', 'マグネッツ２号', 'Normal Monster', 'Warrior', 'EARTH', 3, 500, 1000, '擅长配合的战士，表面涂有电磁的铠甲非常坚固。'),
(4423206, 'M-X-Saber Invoker', 'M.X－军刀 招来者', 'M.X－セイバー インヴォーカー', 'XYZ Monster', 'Warrior', 'EARTH', 3, 1600, 500, '3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。把1只战士族或兽战士族的地属性·4星怪兽从卡组守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(18631392, 'Ma''at', '玛特', 'マアト', 'Effect Monster', 'Fairy', 'LIGHT', 10, -1, -1, '这张卡不能通常召唤。把自己场上表侧表示存在的1只龙族·光属性怪兽和1只天使族·光属性怪兽送去墓地的场合才能特殊召唤。1回合1次，宣言3个卡名才能发动。从自己卡组上面把3张卡翻开，宣言的卡加入手卡。那以外的翻开的卡全部送去墓地。这张卡的攻击力·守备力变成这个效果加入手卡的卡数量×1000的数值。'),
(98795934, 'Mabarrel', '魔加农', 'マキャノン', 'Normal Monster', 'Fiend', 'DARK', 5, 1700, 1400, '大炮状的恶魔。以飞快的速度发射眼球弹。'),
(23469398, 'Machina Air Raider', '机甲部队・空袭机', 'マシンナーズ・エアレイダー', 'Effect Monster', 'Machine', 'EARTH', 8, 1500, 2600, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡以外的1只「机甲」怪兽丢弃才能发动。这张卡从手卡特殊召唤。 ②：对方回合，以自己场上1只机械族怪兽为对象才能发动。和那只怪兽卡名不同并持有那只怪兽的等级以下的等级的1只「机甲」怪兽从卡组特殊召唤，作为对象的怪兽破坏。'),
(31828916, 'Machina Armored Unit', '机甲部队的最前线', '機甲部隊の最前線', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，机械族怪兽被战斗破坏送去自己墓地时才能发动。比墓地的那只怪兽攻击力低的1只相同属性的机械族怪兽从卡组特殊召唤。'),
(39284521, 'Machina Cannon', '机甲部队・加农炮', 'マシンナーズ・カノン', 'Effect Monster', 'Machine', 'EARTH', 8, NULL, 2200, '这张卡不能通常召唤。把这张卡以外的手卡的机械族怪兽任意数量送去墓地的场合可以特殊召唤。 ①：这张卡的攻击力上升因为这张卡特殊召唤而送去墓地的怪兽数量×800。'),
(87074380, 'Machina Citadel', '机甲部队・上校', 'マシンナーズ・カーネル', 'Effect Monster', 'Machine', 'EARTH', 10, 3000, 2500, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，以自己场上1只机械族怪兽为对象才能发动。那只机械族怪兽和持有那个攻击力以下的攻击力的对方场上的怪兽全部破坏。 ②：这张卡在墓地存在的状态，「机甲上校」以外的自己场上的表侧表示的机械族·地属性怪兽被战斗·效果破坏的场合才能发动。这张卡特殊召唤。'),
(96384007, 'Machina Defender', '机甲部队・防卫兵', 'マシンナーズ・ディフェンダー', 'Flip Effect Monster', 'Machine', 'EARTH', 4, 1200, 1800, '①：这张卡反转的场合发动。从卡组把1只「督战官 科文顿」加入手卡。'),
(13247801, 'Machina Defense Perimeter', '机甲部队的防卫圈', '機甲部隊の防衛圏', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有7星以上的机械族怪兽存在，对方不能选择自己场上的6星以下的机械族怪兽作为攻击对象，也不能作为效果的对象。 ②：自己场上的表侧表示的机械族怪兽被战斗·效果破坏的场合，以自己墓地1只机械族怪兽为对象才能发动。那只怪兽加入手卡。'),
(58054262, 'Machina Force', '机甲部队・武力', 'マシンナーズ・フォース', 'Effect Monster', 'Machine', 'EARTH', 10, 4600, 4100, '这张卡不能通常召唤。「督战官 科文顿」的效果才能特殊召唤。 ①：这张卡若不支付1000基本分则不能攻击宣言。 ②：把场上的这张卡送去墓地，以自己墓地的「机甲士兵」「机甲狙击兵」「机甲卫兵」各1只为对象才能发动。那些怪兽特殊召唤。'),
(5556499, 'Machina Fortress', '机甲部队・要塞', 'マシンナーズ・フォートレス', 'Effect Monster', 'Machine', 'EARTH', 7, 2500, 1600, '①：这张卡可以把等级合计直到8以上的手卡的机械族怪兽丢弃，从手卡·墓地特殊召唤（把自身丢弃的场合，从墓地特殊召唤）。 ②：只要这张卡在怪兽区域存在，这张卡为对象发动的对方怪兽的效果适用之际，把对方手卡确认，从那之中选1张卡丢弃。 ③：这张卡被战斗破坏送去墓地的场合，以对方场上1张卡为对象发动。那张对方的卡破坏。'),
(42940404, 'Machina Gearframe', '机甲部队・齿轮传动架', 'マシンナーズ・ギアフレーム', 'Union Effect Monster', 'Machine', 'EARTH', 4, 1800, NULL, '①：这张卡召唤成功时才能发动。从卡组把「机甲机械骨架」以外的1只「机甲」怪兽加入手卡。 ②：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只机械族怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。'),
(50863093, 'Machina Irradiator', '机甲部队・放射机', 'マシンナーズ・ラディエーター', 'Effect Monster', 'Machine', 'EARTH', 8, 1700, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡以外的1只「机甲」怪兽丢弃才能发动。这张卡从手卡特殊召唤。 ②：以自己场上1只机械族怪兽为对象才能发动。从自己墓地选和那只怪兽卡名不同并持有那只怪兽的等级以下的等级的1只「机甲」怪兽特殊召唤，作为对象的怪兽破坏。'),
(51617185, 'Machina Megaform', '机甲部队・超级型态', 'マシンナーズ・メガフォーム', 'Effect Monster', 'Machine', 'EARTH', 8, 2600, 1500, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡解放才能发动。从手卡·卡组把「机甲部队·超大变形」以外的1只「机甲」怪兽特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的「机甲要塞」被送去自己墓地的场合，把那1只「机甲要塞」从墓地除外才能发动。这张卡特殊召唤。'),
(69838761, 'Machina Metalcruncher', '机甲部队・金属粉碎爪', 'マシンナーズ・メタルクランチ', 'Effect Monster', 'Machine', 'EARTH', 9, 2800, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上没有表侧表示的卡存在的场合，这张卡可以不用解放作召唤。 ②：这张卡的①的方法召唤的这张卡的原本攻击力变成1800。 ③：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把3只机械族·地属性怪兽给对方观看，对方从那之中随机选1只。那1只怪兽加入自己手卡，剩下的怪兽回到卡组。'),
(59741415, 'Machina Overdrive', '机甲部队的超临界', '機甲部隊の超臨界', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只机械族怪兽为对象才能发动。和那只怪兽卡名不同的1只「机甲」怪兽从手卡·卡组特殊召唤，作为对象的怪兽破坏。 ②：把墓地的这张卡除外，从自己墓地的怪兽以及除外的自己怪兽之中以3只机械族怪兽为对象才能发动。那些怪兽加入卡组洗切。那之后，自己从卡组抽1张。'),
(78349103, 'Machina Peacekeeper', '机甲部队・维和者', 'マシンナーズ・ピースキーパー', 'Union Effect Monster', 'Machine', 'EARTH', 2, 500, 400, '①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只机械族怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：场上的这张卡被破坏送去墓地时才能发动。从卡组把1只同盟怪兽加入手卡。'),
(85136114, 'Machina Possesstorage', '机甲部队・夺舍封存体', 'マシンナーズ・パゼストレージ', 'Effect Monster', 'Machine', 'DARK', 4, 1600, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以「机甲魔化仓库兵」以外的自己墓地1只「机甲」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把效果发动。 ②：以这张卡以外的自己场上1只「机甲」怪兽和对方场上1张魔法·陷阱卡为对象才能发动。那些卡回到持有者手卡。'),
(86852702, 'Machina Redeployment', '机甲部队的再编制', '機甲部隊の再編制', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●丢弃1张手卡才能发动。从卡组把2只「机甲」怪兽加入手卡（同名卡最多1张）。 ●从手卡丢弃1张「机甲」卡才能发动。从卡组把「机甲部队的再编制」以外的2张「机甲」卡加入手卡（同名卡最多1张）。'),
(54563536, 'Machina Resavenger', '机甲部队・破损储藏体', 'マシンナーズ・リザーブレイク', 'Effect Monster', 'Machine', 'DARK', 4, 1200, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡送去墓地，以自己场上1只「机甲」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1200。这个效果在对方回合也能发动。 ②：这张卡在墓地存在，自己的「机甲」怪兽战斗破坏对方怪兽时才能发动。这张卡加入手卡。'),
(46033517, 'Machina Ruinforce', '机甲部队 蹂躏武力', 'マシンナーズ・ルインフォース', 'Effect Monster', 'Machine', 'DARK', 10, 4600, 4100, '这张卡不能通常召唤。把等级合计直到12以上的自己墓地的机械族怪兽除外的场合才能从墓地特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：战斗阶段对方把效果发动时，把基本分支付一半才能发动。那个发动无效，对方基本分变成一半。 ②：这张卡被战斗·效果破坏的场合才能发动。等级合计最多到12星以下为止，选除外的最多3只自己的「机甲」怪兽特殊召唤。'),
(23782705, 'Machina Sniper', '机甲部队・狙击兵', 'マシンナーズ・スナイパー', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 800, '①：只要这张卡在怪兽区域存在，双方不能向「机甲狙击兵」以外的「机甲」怪兽攻击。'),
(60999392, 'Machina Soldier', '机甲部队・士兵', 'マシンナーズ・ソルジャー', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 1500, '①：自己场上没有其他怪兽存在，这张卡召唤成功时才能发动。从手卡把「机甲士兵」以外的1只「机甲」怪兽特殊召唤。'),
(45674286, 'Machina Unclaspare', '机甲部队・断链备用体', 'マシンナーズ・アンクラスペア', 'Effect Monster', 'Machine', 'DARK', 4, 1800, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族怪兽不能特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「机甲未分类备用兵」以外的1只「机甲」怪兽送去墓地。'),
(11398951, 'Machine Angel Absolute Ritual', '机械天使的绝对仪式', '機械天使の絶対儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「电子化天使」仪式怪兽的降临必需。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而从自己墓地让天使族或者战士族的怪兽回到卡组，从手卡把1只「电子化天使」仪式怪兽仪式召唤。'),
(300302035, 'Machine Angel Ascension', NULL, NULL, 'Skill Card', 'Alexis Rhodes', NULL, NULL, NULL, NULL, NULL),
(39996157, 'Machine Angel Ritual', '机械天使的仪式', '機械天使の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「电子化天使」仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「电子化天使」仪式怪兽仪式召唤。 ②：自己场上的光属性怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(25518020, 'Machine Assembly Line', '机器开发工厂', 'マシン・デベロッパー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上表侧表示存在的机械族怪兽的攻击力上升200。每次场上存在的机械族怪兽被破坏，给这张卡放置2个废品指示物。可以把这张卡送去墓地，从自己墓地选择持有这张卡放置的废品指示物数量以下的等级的1只机械族怪兽特殊召唤。'),
(38116136, 'Machine Attacker', '机器攻击者', 'マシン・アタッカー', 'Normal Monster', 'Machine', 'EARTH', 5, 1600, 1300, '特攻用的机械。以突击之力打倒敌人。'),
(25769732, 'Machine Conversion Factory', '机械改造工厂', '機械改造工場', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '机械族怪兽可以装备。装备怪兽的攻击力·守备力上升300。'),
(63995093, 'Machine Duplication', '机械复制术', '機械複製術', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只攻击力500以下的机械族怪兽为对象才能发动。把最多2只那只怪兽的同名怪兽从卡组特殊召唤。'),
(46700124, 'Machine King', '机械王', '機械王', 'Effect Monster', 'Machine', 'EARTH', 6, 2200, 2000, '每1只在场上表侧表示存在的机械族怪兽，这张卡的攻击力上升100。'),
(70406920, 'Machine King - 3000 B.C.', '机械王-B.C.3000', '機械王－B.C.３０００', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后变成怪兽卡（机械族·地·4星·攻/守1000）在自己的怪兽卡区域特殊召唤。只在这个效果特殊召唤的场合，1回合1次，可以把自己场上存在的1只机械族怪兽解放，这张卡的攻击力直到结束阶段时上升解放的怪兽的攻击力数值。这张卡发动的回合，自己不能把怪兽召唤·特殊召唤。（这张卡也当作陷阱卡使用）'),
(89222931, 'Machine King Prototype', '机械王-原型', '機械王－プロトタイプ', 'Effect Monster', 'Machine', 'EARTH', 3, 1600, 1500, '场上存在的这张卡以外的机械族怪兽每有1只，这张卡的攻击力·守备力上升100。'),
(96938777, 'Machine Lord Ur', '神机王 乌尔', '神機王ウル', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 1500, '①：这张卡可以向对方怪兽全部各作1次攻击。 ②：这张卡进行战斗的场合，对方受到的战斗伤害变成0。'),
(30241314, 'Macro Cosmos', '宏观宇宙', 'マクロコスモス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，可以从手卡·卡组把1只「原始太阳 赫利俄斯」特殊召唤。 ②：只要这张卡在魔法与陷阱区域存在，被送去墓地的卡不去墓地而除外。'),
(94664694, 'Mad Archfiend', '狂暴恶魔', 'マッド・デーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, NULL, '①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：攻击表示的这张卡被选择作为攻击对象的场合发动。这张卡变成守备表示。'),
(79182538, 'Mad Dog of Darkness', '暗黑之狂犬', '暗黒の狂犬', 'Normal Monster', 'Beast', 'DARK', 4, 1900, 1400, '原本曾经是在公园玩耍的普通狗类，但是由于黑暗的力量而凶暴化了。'),
(86993168, 'Mad Hacker', '疯帽骇客', 'マッド・ハッカー', 'Effect Monster', 'Cyberse', 'DARK', 2, 1000, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：对方场上有怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：自己·对方的结束阶段，把场上的这张卡除外才能发动。得到对方场上1只攻击力最低的怪兽的控制权。只要那只怪兽在自己场上表侧表示存在，那只怪兽不能把效果发动，自己不是连接怪兽不能从额外卡组特殊召唤。'),
(97240270, 'Mad Lobster', '狂怒龙虾', 'マッド・ロブスター', 'Normal Monster', 'Aqua', 'WATER', 3, 1700, 1000, '作为被全世界的美食家怪兽们所喜爱的高级食材而闻名。可怕的味道据说很刺激。'),
(18760514, 'Mad Mauler', '疯狂谋杀者', 'マッドマーダー', 'Tuner Monster', 'Zombie', 'DARK', 2, 400, 200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「僵尸带菌者」使用。 ②：这张卡在墓地存在的场合，以自己场上1只6星以上的怪兽为对象才能发动。那只怪兽的等级下降2星，这张卡特殊召唤。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是不死族怪兽不能特殊召唤。'),
(31034919, 'Mad Reloader', '上膛狂魔', 'マッド・リローダー', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '①：这张卡被战斗破坏送去墓地的场合发动。选2张手卡送去墓地，自己从卡组抽2张。'),
(79870141, 'Mad Sword Beast', '猛进的剑角兽', '猛進する剣角獣', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1400, 1200, '攻击守备表示的怪兽时，这张卡的攻击力超过守备表示怪兽的守备力，对方受到这个超过的数值的战斗伤害。'),
(96127902, 'Made to Order Mermaid Outfit Outfitter', '相当魅涌的接单水产', 'かなり魅湧な受注水産', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方墓地1张卡为对象才能发动。那张卡除外。那之后，可以把1张那张卡的同名卡从卡组加入手卡。'),
(43905751, 'Madjinn Gunn', '魔人铳', '魔人銃', 'Normal Monster', 'Fiend', 'DARK', 2, 600, 800, '从口中能够发射子弹攻击的生物兵器。'),
(34680482, 'Madolche Anjelly', '魔幻甜点・果冻天使', 'マドルチェ・エンジェリー', 'Effect Monster', 'Fairy', 'EARTH', 4, 1000, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：把这张卡解放才能发动。从卡组把1只「魔偶甜点」怪兽特殊召唤。这个效果特殊召唤的怪兽不会被战斗破坏，下次的自己回合的结束阶段回到卡组。 ②：这张卡被对方破坏送去墓地的场合发动。这张卡回到卡组。'),
(49374988, 'Madolche Baaple', '魔幻甜点・枫糖咩咩', 'マドルチェ・メェプル', 'Effect Monster', 'Beast', 'EARTH', 3, NULL, 1800, '这张卡被对方破坏送去墓地时，这张卡回到卡组。1回合1次，选择自己场上表侧攻击表示存在的1只名字带有「魔偶甜点」的怪兽和对方场上表侧攻击表示存在的1只怪兽才能发动。选择的2只怪兽变成表侧守备表示，直到下次的对方回合结束时，选择的怪兽不能把表示形式变更。'),
(48252330, 'Madolche Butlerusk', '魔幻甜点・面包干管家', 'マドルチェ・バトラスク', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1500, 800, '这张卡被对方破坏送去墓地时，这张卡回到卡组。这张卡召唤成功时，场上有这张卡以外的名字带有「魔偶甜点」的怪兽存在的场合，可以从卡组把1张场地魔法卡加入手卡。'),
(14001430, 'Madolche Chateau', '魔幻甜点・城堡', 'マドルチェ・シャトー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，自己墓地有「魔偶甜点」怪兽存在的场合，那些全部回到卡组。 ②：只要这张卡在场地区域存在，场上的「魔偶甜点」怪兽的攻击力·守备力上升500。 ③：「魔偶甜点」怪兽的效果让自己墓地的怪兽回到卡组的场合，也能不回到卡组回到手卡。'),
(26570480, 'Madolche Chickolates', '魔幻甜点・巧克力哔哔', 'マドルチェ・ピョコレート', 'Effect Monster', 'Beast', 'EARTH', 3, 800, 1500, '这张卡被对方破坏送去墓地时，这张卡回到卡组。此外，1回合1次，这张卡在场上表侧表示存在，自己场上的名字带有「魔偶甜点」的怪兽的表示形式变更时才能发动。选择场上1只怪兽变成表侧守备表示，那只怪兽是名字带有「魔偶甜点」的怪兽以外的场合，那只怪兽不能攻击，效果无效化。'),
(75363626, 'Madolche Chouxvalier', '魔幻甜点・泡芙骑士', 'マドルチェ・シューバリエ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 1300, '这张卡被对方破坏送去墓地时，这张卡回到卡组。此外，只要这张卡在场上表侧表示存在，对方不能选择「魔偶甜点·泡芙骑士」以外的名字带有「魔偶甜点」的怪兽作为攻击对象。'),
(89521713, 'Madolche Cruffssant', '魔幻甜点・可颂汪汪', 'マドルチェ・クロワンサン', 'Effect Monster', 'Beast', 'EARTH', 3, 1500, 1200, '这张卡被对方破坏送去墓地时，这张卡回到卡组。此外，1回合1次，选择这张卡以外的自己场上1张名字带有「魔偶甜点」的卡才能发动。选择的卡回到手卡，这张卡的等级上升1星，攻击力上升300。'),
(51650038, 'Madolche Dessert', '魔幻甜点・餐后甜品', 'マドルチェ・デセール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以包含「魔偶甜点」怪兽的场上2只效果怪兽为对象才能发动。那些效果怪兽回到手卡·额外卡组。那之后，可以把回去的怪兽的原本攻击力合计以下的攻击力的1只「魔偶甜点」怪兽从手卡·额外卡组特殊召唤。 ②：这张卡在墓地存在的状态，自己墓地的「魔偶甜点」卡回到卡组·额外卡组的场合才能发动。把这张卡作为自己场上1只超量怪兽的超量素材。'),
(96150936, 'Madolche Fresh Sistart', '魔幻甜点见习・鲜果挞修女', 'フレッシュマドルチェ・シスタルト', 'Link Monster', 'Fairy', 'EARTH', NULL, 1500, NULL, '「魔偶甜点」怪兽2只 ①：只要这张卡所连接区有「魔偶甜点」怪兽存在，自己场上的「魔偶甜点」魔法·陷阱卡不会被效果破坏，双方不能把那些卡作为效果的对象。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替让自己墓地1只「魔偶甜点」怪兽回到卡组。'),
(91350799, 'Madolche Hootcake', '魔幻甜点・松饼咕咕', 'マドルチェ・ホーットケーキ', 'Effect Monster', 'Beast', 'EARTH', 3, 1500, 1100, '这个卡名的①的效果1回合只能使用1次。 ①：以自己墓地1只怪兽为对象才能发动。那只怪兽除外，从卡组把「魔偶甜点·热香饼猫头鹰」以外的1只「魔偶甜点」怪兽特殊召唤。 ②：这张卡被对方破坏送去墓地的场合发动。这张卡回到卡组。'),
(12940613, 'Madolche Lesson', '魔幻甜点・礼仪', 'マドルチェ・マナー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地1只名字带有「魔偶甜点」的怪兽回到卡组，自己场上存在的全部名字带有「魔偶甜点」的怪兽的攻击力·守备力上升800。那之后，可以选自己墓地1只怪兽回到卡组。'),
(11868731, 'Madolche Magileine', '魔幻甜点・玛德琳魔女', 'マドルチェ・マジョレーヌ', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1400, 1200, '①：这张卡召唤·反转召唤时才能发动。从卡组把1只「魔偶甜点」怪兽加入手卡。 ②：这张卡被对方破坏送去墓地的场合发动。这张卡回到卡组。'),
(26016357, 'Madolche Marmalmaide', '魔幻甜点・柑橘酱女仆', 'マドルチェ・マーマメイド', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 800, 2000, '这张卡被对方破坏送去墓地时，这张卡回到卡组。这张卡反转时，可以选择自己墓地1张名字带有「魔偶甜点」的魔法·陷阱卡加入手卡。'),
(52404456, 'Madolche Messengelato', '魔幻甜点・冰糕邮递员', 'マドルチェ・メッセンジェラート', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1000, '①：这张卡特殊召唤时才能发动。从卡组把1张「魔偶甜点」魔法·陷阱卡加入手卡。这个效果在自己场上有兽族「魔偶甜点」怪兽存在的场合才能发动和处理。 ②：这张卡被对方破坏送去墓地的场合发动。这张卡回到卡组。'),
(12980373, 'Madolche Mewfeuille', '魔幻甜点・千层咪咪', 'マドルチェ・ミィルフィーヤ', 'Effect Monster', 'Beast', 'EARTH', 3, 500, 300, '这张卡被对方破坏送去墓地时，这张卡回到卡组。这张卡召唤成功时，可以从手卡把1只名字带有「魔偶甜点」的怪兽特殊召唤。'),
(38745241, 'Madolche Mini Meowcaroons', '迷你喵魔幻甜点・玛卡龙喵喵', 'ミニャーマドルチェ・ニャカロン', 'Link Monster', 'Beast', 'EARTH', NULL, 2300, NULL, '包含「魔偶甜点」怪兽的效果怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1张「魔偶甜点」卡加入手卡。 ②：以自己墓地1只怪兽为对象才能发动。从手卡把1只「魔偶甜点」怪兽特殊召唤，作为对象的怪兽回到卡组。这个效果的发动后，直到回合结束时自己不能把「魔偶甜点」怪兽以外的怪兽的效果发动。'),
(79759367, 'Madolche Nights', '魔幻甜点玩偶之夜', '魔導人形の夜', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己墓地没有怪兽存在的场合才能发动。效果怪兽的效果的发动无效。自己场上有「魔偶甜点·布丁公主」存在的场合，再让对方手卡随机1张回到卡组。'),
(77848740, 'Madolche Petingcessoeur', '魔幻甜点・布蕾小公主', 'マドルチェ・プティンセスール', 'Effect Monster', 'Fairy', 'EARTH', 4, 1400, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己墓地没有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。从手卡·卡组把「魔偶甜点·布丁妹公主」以外的1只「魔偶甜点」怪兽特殊召唤。那只怪兽的等级下降1星。这个回合，自己不是「魔偶甜点」怪兽不能特殊召唤。 ③：这张卡被对方破坏送去墓地的场合发动。这张卡回到卡组。'),
(68159562, 'Madolche Promenade', '魔幻甜点・漫步', 'マドルチェ・プロムナード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以对方场上1张表侧表示卡和自己的场上·墓地1只「魔偶甜点」怪兽为对象才能发动。那张对方的卡的效果直到回合结束时无效，那只自己怪兽回到手卡。 ②：把墓地的这张卡除外，以自己场上1只「魔偶甜点」超量怪兽为对象才能发动。从自己的手卡·卡组·墓地选1只「魔偶甜点」怪兽作为成为对象的怪兽的超量素材。'),
(74641045, 'Madolche Puddingcess', '魔幻甜点・布丁公主', 'マドルチェ・プディンセス', 'Effect Monster', 'Fairy', 'EARTH', 5, 1000, 1000, '①：自己墓地没有怪兽存在的场合，这张卡的攻击力·守备力上升800。 ②：这张卡和对方怪兽进行战斗的伤害计算后，以对方场上1张卡为对象才能发动。那张对方的卡破坏。 ③：这张卡被对方破坏送去墓地的场合发动。这张卡回到卡组。'),
(44311445, 'Madolche Puddingcess Chocolat-a-la-Mode', '魔幻甜点・布丁公主・巧克力风味', 'マドルチェ・プディンセス・ショコ・ア・ラ・モード', 'XYZ Monster', 'Fairy', 'EARTH', 5, 2500, 2200, '地属性5星怪兽×2 这张卡也能在自己场上的4阶以下的「魔偶甜点」超量怪兽上面重叠来超量召唤。 ①：1回合1次，以自己墓地1张「魔偶甜点」卡为对象才能发动。那张卡回到卡组。 ②：这张卡有「魔偶甜点·布丁公主」在作为超量素材的状态，自己墓地的「魔偶甜点」卡回到卡组时，把这张卡1个超量素材取除才能发动。从卡组把1只「魔偶甜点」怪兽表侧攻击表示或里侧守备表示特殊召唤。'),
(49689480, 'Madolche Queen Tiarafraise', '魔幻甜点女王・后冠草莓提拉米苏', 'クイーンマドルチェ・ティアラフレース', 'XYZ Monster', 'Fairy', 'EARTH', 5, 2600, 2500, '5星「魔偶甜点」怪兽×3 「魔偶甜点后·后冠草莓提拉米苏」1回合1次也能在自己场上的「魔偶甜点后·后冠提拉米苏」上面重叠来超量召唤。 ①：对方回合1次，把这张卡1个超量素材取除，以自己墓地最多2张「魔偶甜点」卡为对象才能发动。那些卡回到卡组，让最多有回去数量的对方场上的卡回到卡组。 ②：这张卡被对方破坏送去墓地的场合发动。这张卡回到额外卡组。'),
(37164373, 'Madolche Queen Tiaramisu', '魔幻甜点女王・后冠提拉米苏', 'クイーンマドルチェ・ティアラミス', 'XYZ Monster', 'Fairy', 'EARTH', 4, 2200, 2100, '4星「魔偶甜点」怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己墓地最多2张「魔偶甜点」卡为对象才能发动。那些卡回到卡组，让最多有回去数量的对方场上的卡回到卡组。'),
(71348837, 'Madolche Salon', '魔幻甜点・沙龙', 'マドルチェ・サロン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「魔偶甜点」怪兽召唤。 ②：这张卡在魔法与陷阱区域存在的状态，自己的场上（表侧表示）·墓地的「魔偶甜点」卡因效果回到自己的手卡·卡组的场合发动。从卡组把「魔偶甜点沙龙」以外的1张「魔偶甜点」魔法·陷阱卡在自己场上盖放。'),
(75833426, 'Madolche Tea Break', '魔幻甜点・茶歇', 'マドルチェ・ティーブレイク', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己墓地没有怪兽存在的场合才能发动。魔法·陷阱卡的发动无效，那张卡回到持有者手卡。自己场上有「魔偶甜点·布丁公主」存在的场合，可以再选对方场上1张卡破坏。'),
(20343502, 'Madolche Teacher Glassouffle', '魔幻甜点教师・眼镜舒芙蕾', 'ティーチャーマドルチェ・グラスフレ', 'XYZ Monster', 'Fairy', 'EARTH', 4, 1800, 2500, '4星「魔偶甜点」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡1个超量素材取除，以场上1只「魔偶甜点」怪兽为对象才能发动。这个回合，那只表侧表示怪兽不受自身以外的怪兽的效果影响。 ②：这张卡在怪兽区域存在的状态，「魔偶甜点」卡被送去自己墓地的场合才能发动。自己·对方的墓地的卡合计最多2张回到卡组。'),
(60470713, 'Madolche Ticket', '魔幻甜点・邀请函', 'マドルチェ・チケット', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在魔法与陷阱区域存在的状态，自己的场上（表侧表示）·墓地的「魔偶甜点」卡因效果回到自己的手卡·卡组的场合发动。从卡组把1只「魔偶甜点」怪兽加入手卡。自己场上有天使族「魔偶甜点」怪兽存在的场合，也能不加入手卡攻击表示特殊召唤。'),
(48439321, 'Madolche Waltz', '魔幻甜点・华尔兹', 'マドルチェ・ワルツ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上的名字带有「魔偶甜点」的怪兽进行战斗的伤害计算后，给与对方基本分300分伤害。'),
(23681456, 'Madolchepalooza', '魔幻甜点・欢乐庆典', 'マドルチェ・ハッピーフェスタ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡把名字带有「魔偶甜点」的怪兽任意数量特殊召唤。这个效果特殊召唤的怪兽在结束阶段时回到持有者卡组。'),
(25341652, 'Maestroke the Symphony Djinn', '交响魔人 剑击指挥', '交響魔人マエストローク', 'XYZ Monster', 'Fiend', 'DARK', 4, 1800, 2300, '4星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择对方场上表侧攻击表示存在的1只怪兽才能发动。选择的怪兽变成里侧守备表示。此外，只要这张卡在场上表侧表示存在，自己场上的名字带有「魔人」的超量怪兽被破坏的场合，可以作为代替把那怪兽1个超量素材取除。'),
(83746708, 'Mage Power', '魔导师之力', '魔導師の力', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力·守备力上升自己场上的魔法·陷阱卡数量×500。'),
(26534688, 'Magellanica, the Deep Sea City', '深海之都 墨瓦腊泥加', '深海の都 マガラニカ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名在规则上当作「海」使用。 ①：作为这张卡的发动时的效果处理，可以从卡组选1只水属性怪兽在卡组最上面放置。 ②：1回合1次，以自己场上1只水属性怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升1星或者2星。 ③：1回合1次，自己主要阶段，自己对水属性同调怪兽的特殊召唤成功的场合才能发动。把对方手卡确认，从那之中选1张卡直到结束阶段表侧表示除外。'),
(10000030, 'Magi Magi ☆ Magician Gal', '眼盯盯☆魔术辣妹', 'マジマジ☆マジシャンギャル', 'XYZ Monster', 'Spellcaster', 'DARK', 6, 2400, 2000, '魔法师族6星怪兽×2 1回合1次，可以把这张卡1个超量素材取除，把1张手卡从游戏中除外从以下效果选择1个发动。 ●选择对方场上1只怪兽直到这个回合的结束阶段时得到控制权。 ●选择对方墓地1只怪兽在自己场上特殊召唤。'),
(59080, 'Magia Magic - Thunder of Judgment', '圣魔 审判之雷', '聖魔 裁きの雷', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「大贤者」卡、「恩底弥翁」卡使用。 ①：可以把自己场上1张其他的表侧表示的「大贤者」卡送去墓地或2个魔力指示物取除，从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●从自己的手卡·额外卡组（表侧）·墓地把1只魔法师族怪兽特殊召唤。 ●场上1张其他卡除外。'),
(62279055, 'Magic Cylinder', '魔法之筒', '魔法の筒', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时，以1只攻击怪兽为对象才能发动。那只攻击怪兽的攻击无效，给与对方那个攻击力数值的伤害。'),
(96474800, 'Magic Deflector', '魔法偏转器', 'マジック・ディフレクター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个回合，场上的装备·场地·永续·速攻魔法卡的效果无效。'),
(59344077, 'Magic Drain', '魔力抽取', 'マジック・ドレイン', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '对方的魔法发动的时候才可以发动。对方从手卡丢弃1张魔法卡就可以使这张卡无效化。如果对方不丢弃的场合，对方的魔法卡的发动无效化并破坏。'),
(67227834, 'Magic Formula', '魔术咒文书', '魔術の呪文書', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「黑魔术师」「黑魔术少女」才能装备。装备怪兽的攻击力上升700。这张卡从场上送去墓地时，自己回复1000基本分。'),
(49941059, 'Magic Gate of Miracles', '奇迹之魔术门', '奇跡のマジック・ゲート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有魔法师族怪兽2只以上存在的场合才能发动。选对方场上1只攻击表示怪兽变成守备表示。那之后，得到那只怪兽的控制权。这个效果得到控制权的怪兽不会被战斗破坏。'),
(22530212, 'Magic Hand', '魔术手', 'マジック・ハンド', 'Effect Monster', 'Spellcaster', 'DARK', 4, 800, 1600, '①：只在这张卡在场上表侧表示存在才有1次，对方用抽卡以外的方法从卡组把卡加入手卡时才能发动。那卡送去墓地，给与对方800伤害。'),
(82458280, 'Magic Hole Golem', '魔孔石人', 'マジック・ホール・ゴーレム', 'Effect Monster', 'Rock', 'DARK', 3, NULL, 2000, '1回合1次，选择自己场上表侧表示存在的1只怪兽才能发动。选择的怪兽直到结束阶段时攻击力变成一半数值，这个回合可以直接攻击对方玩家。这个效果发动的回合，选择的怪兽以外的怪兽不能攻击。'),
(77414722, 'Magic Jammer', '魔法干扰阵', 'マジック・ジャマー', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：魔法卡发动时，丢弃1张手卡才能发动。那个发动无效并破坏。'),
(1073952, 'Magic Planter', '魔术花盆', 'マジック・プランター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1张表侧表示的永续陷阱卡送去墓地才能发动。自己抽2张。'),
(61844784, 'Magic Reflector', '魔法防护器', 'マジック・ガードナー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1张魔法卡才能发动。给选择的卡放置1个指示物。选择的卡被破坏的场合，作为代替把1个指示物取除。'),
(64990807, 'Magic Triangle of the Ice Barrier', '冰结界的三方阵', '氷結界の三方陣', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把卡名不同的手卡3只「冰结界」怪兽给对方观看，以对方场上1张卡为对象才能发动。那张对方的卡破坏，从手卡把1只「冰结界」怪兽特殊召唤。'),
(10239627, 'Magical Abductor', '魔力诱导者', 'マジカル・アブダクター', 'Pendulum Effect Monster', 'Spellcaster', 'EARTH', 4, 1700, 1400, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ②：这张卡的攻击力上升这张卡的魔力指示物数量×100。 ③：1回合1次，把这张卡3个魔力指示物取除才能发动。从卡组把1只魔法师族·1星怪兽加入手卡。'),
(43385557, 'Magical Android', '魔力人造机人', 'マジカル・アンドロイド', 'Synchro Monster', 'Psychic', 'LIGHT', 5, 2400, 1700, '调整＋调整以外的怪兽1只以上 自己的结束阶段时，回复自己场上表侧表示存在的念动力族怪兽数量×600的数值的基本分。'),
(96008713, 'Magical Arm Shield', '魔术臂盾', 'マジックアーム・シールド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上有表侧表示怪兽2只以上存在，自己场上有怪兽存在的场合，对方怪兽的攻击宣言时以攻击怪兽以外的对方场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽的控制权直到战斗阶段结束时得到，攻击对象转移为那只怪兽进行伤害计算。'),
(91819979, 'Magical Blast', '魔法爆破', 'マジックブラスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：给与对方为自己场上的魔法师族怪兽数量×200伤害。 ②：这张卡在墓地存在的场合，自己抽卡阶段的抽卡前才能发动。作为这个回合进行通常抽卡的代替，这张卡加入手卡。'),
(72171665, 'Magical Broker', '魔导暗商人', '魔導闇商人', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1500, 200, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有永续魔法·永续陷阱卡存在，这张卡不会被战斗·效果破坏。 ②：对方回合，把自己场上1张表侧表示的永续魔法·永续陷阱卡送去墓地才能发动。自己从卡组抽1张。'),
(23220863, 'Magical Cavalry of Cxulub', '苏鲁伯的魔导骑兵', 'シュルブの魔導騎兵', 'Pendulum Effect Monster', 'Dinosaur', 'EARTH', 4, 1500, 1800, '①：这张卡只要在怪兽区域存在，不受灵摆怪兽以外的怪兽发动的效果影响。'),
(39910367, 'Magical Citadel of Endymion', '魔法都市 恩底弥翁', '魔法都市エンディミオン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ②：有魔力指示物放置的卡被破坏的场合把那些卡放置的魔力指示物数量的魔力指示物给这张卡放置。 ③：1回合1次，自己为让卡的效果发动而把自己场上的魔力指示物取除的场合，可以作为代替从这张卡取除。 ④：这张卡被破坏的场合，可以作为代替把这张卡1个魔力指示物取除。'),
(18809562, 'Magical Contract Door', '魔导契约之扉', '魔導契約の扉', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己手卡选1张魔法卡加入对方手卡。那之后，从自己卡组把1只7·8星的暗属性怪兽加入自己手卡。'),
(15943341, 'Magical Cylinders', '再上膛之筒', 'リローデッド・シリンダー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从自己的卡组·墓地选1张「魔法筒」在自己场上盖放。从卡组盖放的场合，那张卡在盖放的回合也能发动。 ②：自己把「魔法筒」发动时，把墓地的这张卡除外才能发动。那个效果给与对方的伤害变成2倍。'),
(28553439, 'Magical Dimension', '次元魔法', 'ディメンション・マジック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上有魔法师族怪兽存在的场合，以自己场上1只怪兽为对象才能发动。那只自己怪兽解放，从手卡把1只魔法师族怪兽特殊召唤。那之后，可以选场上1只怪兽破坏。'),
(6061630, 'Magical Exemplar', '魔法典范者', 'マジカル・コンダクター', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1700, 1400, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置2个魔力指示物。 ②：1回合1次，把这张卡的魔力指示物任意数量取除才能发动。从自己的手卡·墓地选持有和取除数量相同等级的1只魔法师族怪兽特殊召唤。'),
(32723153, 'Magical Explosion', '魔力爆发', 'マジカル・エクスプロージョン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己手卡0张的时候才能发动。给与对方基本分自己墓地存在的魔法卡数量×200分数值的伤害。'),
(46474915, 'Magical Ghost', '魔法幽灵', 'マジカル・ゴースト', 'Normal Monster', 'Zombie', 'DARK', 4, 1300, 1400, '向对方施展法术，使敌人陷入混乱和恐惧，从而胡乱攻击。'),
(81210420, 'Magical Hats', '魔术礼帽', 'マジカルシルクハット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方战斗阶段才能发动。从卡组选2张魔法·陷阱卡，那2张卡当作通常怪兽卡（攻/守0）使用，和自己的主要怪兽区域1只怪兽混合洗切并里侧守备表示盖放。这个效果从卡组特殊召唤的卡不在战斗阶段内不能存在，战斗阶段结束时破坏。'),
(51916853, 'Magical Hound', '魔术猎犬', 'マジカル・ハウンド', 'Tuner Monster', 'Machine', 'EARTH', 1, 500, 800, '这个卡名的效果在决斗中只能使用1次。 ①：这张卡在手卡·墓地存在的场合，以对方场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡回到持有者手卡，这张卡特殊召唤。'),
(35058857, 'Magical King Moonstar', '奇术王 月星', '奇術王 ムーン・スター', 'Effect Monster', 'Fiend', 'DARK', 3, 900, 600, '把这张卡作为同调素材的场合，不是暗属性怪兽的同调召唤不能使用。 ①：自己场上有调整存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以自己的场上（表侧表示）·墓地1只怪兽为对象才能发动。这张卡的等级直到回合结束时变成和那只怪兽相同。这个效果的发动后，直到回合结束时自己不能作同调召唤以外的特殊召唤。'),
(64389297, 'Magical Labyrinth', '迷宫变化', '迷宮変化', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '给「迷宫壁」装备。把「迷宫壁」和装备的这张卡作为祭品，从卡组把「墙壁之影」特殊召唤。'),
(85852291, 'Magical Mallet', '万宝槌', '打ち出の小槌', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己手卡任意数量回到卡组洗切。那之后，自己抽出回到卡组的数量。'),
(8034697, 'Magical Marionette', '魔法操纵人偶', '魔法の操り人形', 'Effect Monster', 'Spellcaster', 'DARK', 5, 2000, 1000, '只要这张卡在场上表侧表示存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。这张卡放置的魔力指示物每有1个，这张卡的攻击力上升200。此外，可以把这张卡放置的2个魔力指示物取除，场上存在的1只怪兽破坏。'),
(47679935, 'Magical Meltdown', '暴走魔法阵', '暴走魔法陣', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「召唤师 阿莱斯特」加入手卡。 ②：只要这张卡在场地区域存在，包含把融合怪兽融合召唤效果的效果由自己发动的场合，那个发动不会被无效化，在那次融合召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。'),
(32362575, 'Magical Merchant', '魔导杂货商人', '魔導雑貨商人', 'Flip Effect Monster', 'Insect', 'LIGHT', 1, 200, 700, '①：这张卡反转的场合发动。直到魔法·陷阱卡出现为止从自己卡组上面翻卡，那张魔法·陷阱卡加入手卡。剩下的翻开的卡全部送去墓地。'),
(71650854, 'Magical Mid-Breaker Field', '半魔导带域', '半魔導帯域', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '自己的主要阶段1·主要阶段2的开始时才能把这张卡发动。 ①：双方的主要阶段1内，场上的怪兽不会成为各自的对方的效果的对象，不会被各自的对方的效果破坏。 ②：只要这张卡在场地区域存在，自己不能把场地魔法卡发动·盖放。'),
(47810543, 'Magical Musket - Crooked Crown', '魔弹－血腥王冠', '魔弾－ブラッディ・クラウン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：「魔弹-血色之冠」在自己场上只能有1张表侧表示存在。 ②：自己·对方的主要阶段才能发动。从手卡把1只「魔弹」怪兽特殊召唤。和这个效果让怪兽特殊召唤的区域相同纵列的对方的主要怪兽区域没有使用的场合，那个区域直到回合结束时不能使用。'),
(93356623, 'Magical Musket - Cross-Domination', '魔弹－交叉主宰者', '魔弾－クロス・ドミネーター', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「魔弹」怪兽存在的场合，以场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只怪兽的攻击力·守备力变成0，效果无效化。'),
(66149377, 'Magical Musket - Dancing Needle', '魔弹－舞跃之针', '魔弾－ダンシング・ニードル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「魔弹」怪兽存在的场合，以自己·对方的墓地的卡合计最多3张为对象才能发动。那些卡除外。'),
(20745268, 'Magical Musket - Desperado', '魔弹－亡命之徒', '魔弾－デスペラード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「魔弹」怪兽存在的场合，以场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(92534075, 'Magical Musket - Fiendish Deal', '魔弹－魔鬼交易', '魔弾－デビルズ・ディール', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：只要这张卡在魔法与陷阱区域存在，自己场上的「魔弹」怪兽不会被效果破坏。 ②：这张卡被对方的效果送去墓地的场合才能发动。从自己的卡组·墓地选「魔弹-恶魔交易」以外的1张「魔弹」卡加入手卡。'),
(29628180, 'Magical Musket - Last Stand', '魔弹－亡者爆击', '魔弾－デッドマンズ・バースト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「魔弹」怪兽存在的场合，对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(67901914, 'Magical Musket - Steady Hands', '魔弹－无尽内啡肽', '魔弾－ネバー・エンドルフィン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「魔弹」怪兽为对象才能发动（这张卡发动的回合，作为对象的怪兽不能直接攻击）。那只怪兽的攻击力·守备力直到回合结束时变成原本数值的2倍。'),
(3287359, 'Magical Musket Mastermind Caspar', '魔弹邪魔 卡斯帕', '魔弾の悪魔 カスパール', 'Link Monster', 'Fiend', 'LIGHT', NULL, 2000, NULL, '包含恶魔族·光属性怪兽的怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动。从手卡·卡组选包含怪兽的2张「魔弹」卡，那之内的1只怪兽在自己场上特殊召唤，另1张在对方场上盖放。 ②：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。'),
(30907810, 'Magical Musket Mastermind Zakiel', '魔弹邪魔 萨米尔', '魔弾の悪魔 ザミエル', 'Effect Monster', 'Fiend', 'LIGHT', 8, 2500, 2500, '这张卡可以把1只「魔弹」怪兽解放表侧表示上级召唤。这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。 ②：对方结束阶段才能发动。自己从卡组抽出这个回合这张卡表侧表示存在期间自己发动的「魔弹」魔法·陷阱卡的数量。'),
(68024506, 'Magical Musketeer Calamity', '魔弹射手 灾星', '魔弾の射手 カラミティ', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1500, 1300, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。 ②：和这张卡相同纵列有魔法·陷阱卡发动的场合，以自己墓地1只「魔弹」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(32841045, 'Magical Musketeer Caspar', '魔弹射手 卡斯帕', '魔弾の射手 カスパール', 'Effect Monster', 'Fiend', 'LIGHT', 3, 1200, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。 ②：和这张卡相同纵列有魔法·陷阱卡发动的场合才能发动。和那张发动的卡卡名不同的1张「魔弹」卡从卡组加入手卡。'),
(68246154, 'Magical Musketeer Doc', '魔弹射手 医生', '魔弾の射手 ドクトル', 'Effect Monster', 'Fiend', 'LIGHT', 3, 1400, 1200, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。 ②：和这张卡相同纵列有魔法·陷阱卡发动的场合才能发动。从自己墓地选和那张发动的卡卡名不同的1张「魔弹」卡加入手卡。'),
(5230799, 'Magical Musketeer Kidbrave', '魔弹射手 小子', '魔弾の射手 ザ・キッド', 'Effect Monster', 'Fiend', 'LIGHT', 3, 1600, 200, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。 ②：和这张卡相同纵列有魔法·陷阱卡发动的场合，从手卡丢弃1张「魔弹」卡才能发动。自己抽2张。'),
(71791814, 'Magical Musketeer Max', '魔弹射手 马克斯', '魔弾の射手 マックス', 'Link Monster', 'Fiend', 'LIGHT', NULL, 1000, NULL, '8星以下的「魔弹」怪兽1只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合，可以从以下效果选择1个发动。 ●把最多有对方场上的怪兽数量的「魔弹」魔法·陷阱卡从卡组加入手卡（同名卡最多1张）。 ●把最多有对方场上的魔法·陷阱卡数量的「魔弹」怪兽从卡组特殊召唤（同名卡最多1张）。 ②：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。'),
(31629407, 'Magical Musketeer Starfire', '魔弹射手 斯塔尔', '魔弾の射手 スター', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1300, 1700, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。 ②：和这张卡相同纵列有魔法·陷阱卡发动的场合才能发动。除「魔弹射手 斯塔尔」外的1只4星以下的「魔弹」怪兽从卡组守备表示特殊召唤。'),
(94418111, 'Magical Musketeer Wild', '魔弹射手 狂野', '魔弾の射手 ワイルド', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1700, 900, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己·对方回合自己可以把「魔弹」魔法·陷阱卡从手卡发动。 ②：和这张卡相同纵列有魔法·陷阱卡发动的场合，以自己墓地3张「魔弹」卡为对象才能发动。那3张卡加入卡组洗切。那之后，自己从卡组抽1张。'),
(7802006, 'Magical Plant Mandragola', '魔草 曼德拉草', '魔草 マンドラゴラ', 'Flip Effect Monster', 'Spellcaster', 'DARK', 2, 500, 200, '反转：给场上表侧表示存在的可以放置魔力指示物的卡全部放置1个魔力指示物。'),
(3918345, 'Magical Reflect Slime', '魔法史莱姆', 'マジック・スライム', 'Gemini Monster', 'Aqua', 'WATER', 3, 700, 1200, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡进行战斗所受到的对控制者的战斗伤害让对方承受。'),
(34206604, 'Magical Scientist', '魔导科学家', '魔導サイエンティスト', 'Effect Monster', 'Spellcaster', 'DARK', 1, 300, 300, '支付1000基本分，就可以从自己的融合卡组中特殊召唤1只6星以下的融合怪兽。这只融合怪兽不能对对方进行直接攻击，回合结束时回到融合卡组。'),
(43930492, 'Magical Something', '吸收魔术师', 'マジックアブソーバー', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 1300, '这个卡名的③的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ②：这张卡的等级上升这张卡的魔力指示物数量的数值。 ③：把这张卡3个魔力指示物取除，以自己墓地1张速攻魔法卡为对象才能发动。那张卡在自己的魔法与陷阱区域盖放。'),
(43455065, 'Magical Spring', '魔力之泉', '魔力の泉', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「魔力之泉」在1回合只能发动1张。 ①：自己从卡组抽出对方场上的表侧表示的魔法·陷阱卡的数量。那之后，从自己手卡选自己场上的表侧表示的魔法·陷阱卡数量的卡丢弃。这张卡的发动后，直到下次的对方回合的结束时，对方场上的魔法·陷阱卡不会被破坏，发动和效果不会被无效化。'),
(18752707, 'Magical Star Illusion', '魔力星幻像', 'マジカル・スター・イリュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的怪兽数量是对方场上的怪兽数量以下的场合才能发动。自己以及对方场上的怪兽的攻击力直到回合结束时上升那怪兽的控制者场上的怪兽的等级合计×100。'),
(98494543, 'Magical Stone Excavation', '魔法石的采掘', '魔法石の採掘', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃2张手卡，以自己墓地1张魔法卡为对象才能发动。那张卡加入手卡。'),
(53119267, 'Magical Thorn', '魔力之棘', '魔力の棘', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的手卡丢弃去墓地时，每丢弃1张卡就给与对方基本分500分的伤害。'),
(85758066, 'Magical Trick Mirror', '机械驱动的魔镜', '機械じかけのマジックミラー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时，以对方墓地1张魔法卡为对象才能发动。那张卡在自己场上盖放。 ②：把墓地的这张卡除外，从手卡以及自己场上盖放的卡之中把1张「死者苏生」送去墓地才能发动。从自己墓地选1只「欧贝利斯克之巨神兵」守备表示特殊召唤。这个效果在对方回合发动的场合，这个回合只要这个效果特殊召唤的怪兽在自己场上存在，可以攻击的对方怪兽必须向那只怪兽作出攻击。'),
(30608985, 'Magical Undertaker', '魔力送葬士', 'マジカル・アンダーテイカー', 'Flip Effect Monster', 'Spellcaster', 'DARK', 2, 400, 400, '①：这张卡反转的场合，以自己墓地1只4星以下的魔法师族怪兽为对象才能发动。那只魔法师族怪兽特殊召唤。'),
(43857222, 'Magicalibra', '天平魔法秤', 'ライブラの魔法秤', 'Pendulum Tuner Effect Monster', 'Spellcaster', 'WATER', 4, 1000, 1000, '拥有意志的天秤。虽然维持着世间的平衡，却常常将锤星放错位置。'),
(24845628, 'Magicalized Duston Mop', '尘妖的拖把', 'ダストンのモップ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽不能解放，也不能作为融合·同调·超量召唤的素材。场上的这张卡被对方的卡的效果破坏送去墓地时，可以从卡组把1只名字带有「尘妖」的怪兽加入手卡。「尘妖的拖把」在自己场上只能有1张表侧表示存在。'),
(11827244, 'Magicalized Fusion', '圆融结合魔术', '円融魔術', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的场上·墓地的怪兽作为融合素材除外，把1只魔法师族融合怪兽融合召唤。'),
(25531465, 'Magicat', '魔法猫', 'マジキャット', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 600, 500, '这张卡被魔法师族怪兽的同调召唤使用送去墓地的场合，可以让自己墓地存在的1张魔法卡回到卡组最上面。'),
(7922915, 'Magician Navigation', '魔术师导门', 'マジシャンズ・ナビゲート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡把1只「黑魔术师」特殊召唤。那之后，从卡组把1只7星以下的魔法师族·暗属性怪兽特殊召唤。 ②：自己场上有「黑魔术师」存在的场合，把这个回合没有送去墓地的这张卡从墓地除外，以对方场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡的效果直到回合结束时无效。'),
(30208479, 'Magician of Black Chaos', '黑混沌之魔导', 'マジシャン・オブ・ブラックカオス', 'Ritual Monster', 'Spellcaster', 'DARK', 8, 2800, 2600, '「混沌-黑魔术的仪式」降临'),
(79613121, 'Magician of Black Chaos MAX', '黑混沌之魔术师·黑混沌极魔导', 'マジシャン・オブ・ブラックカオス・MAX', 'Ritual Effect Monster', 'Spellcaster', 'DARK', 8, 2800, 2600, '「混沌形态」降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，把自己场上1只怪兽解放才能发动。这个回合，对方不能把怪兽的效果发动。 ②：这张卡战斗破坏对方怪兽时，以自己墓地1张魔法卡为对象才能发动。那张卡加入手卡。'),
(47963370, 'Magician of Chaos', '混沌之魔术师', 'マジシャン・オブ・カオス', 'Ritual Effect Monster', 'Spellcaster', 'DARK', 7, 2500, 2100, '「混沌形态」降临。 ①：这张卡的卡名只要在场上·墓地存在当作「黑魔术师」使用。 ②：1回合1次，魔法·陷阱卡的效果发动时，以场上1张卡为对象才能发动。那张卡破坏。 ③：仪式召唤的这张卡被战斗·效果破坏的场合才能发动。从手卡把「混沌之魔术师」以外的1只「混沌」仪式怪兽无视召唤条件特殊召唤。'),
(35191415, 'Magician of Dark Illusion', '黑幻像之魔导', 'マジシャン・オブ・ブラック・イリュージョン', 'Effect Monster', 'Spellcaster', 'DARK', 7, 2100, 2500, '这个卡名的①③的效果1回合各能使用1次。 ①：自己在对方回合把魔法·陷阱卡的效果发动的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡只要在怪兽区域存在，卡名当作「黑魔术师」使用。 ③：只在这张卡在场上表侧表示存在才有1次，自己把魔法·陷阱卡的效果发动的场合以自己墓地1只「黑魔术师」为对象才能发动。那只怪兽特殊召唤。'),
(31560081, 'Magician of Faith', '圣魔术师', '聖なる魔術師', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 1, 300, 400, '①：这张卡反转的场合，以自己墓地1张魔法卡为对象发动。那张卡加入手卡。'),
(67853262, 'Magician of Faithfulness', '神圣魔术师', '神聖なる魔術師', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 5, 600, 800, '这个卡名的效果1回合只能使用1次。 ①：这张卡反转的场合，以自己墓地1张魔法卡为对象才能发动。那张卡加入手卡。那之后，可以从卡组把1只「圣魔术师」或「神圣魔术师」里侧守备表示特殊召唤。'),
(67865534, 'Magician of Hope', '希望的魔术师', '希望の魔術師', 'XYZ Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 4, 2500, 2000, '4星怪兽×2 4星可以灵摆召唤的场合在额外卡组的表侧表示的这张卡可以灵摆召唤。这个卡名的①的怪兽效果1回合只能使用1次。 ①：把这张卡1个超量素材取除才能发动。从手卡把1只7星以下的灵摆怪兽效果无效守备表示特殊召唤。那之后，可以把表侧表示的这张卡在自己的灵摆区域放置。 ②：这张卡灵摆召唤成功的场合，以自己墓地1只灵摆怪兽为对象才能发动。那只怪兽在这张卡下面重叠作为超量素材。'),
(300302013, 'Magician''s Act', NULL, NULL, 'Skill Card', 'Arkana', NULL, NULL, NULL, NULL, NULL),
(50755, 'Magician''s Circle', '魔术师的法阵', 'マジシャンズ・サークル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己或者对方的魔法师族怪兽的攻击宣言时才能发动。双方玩家各自从自己卡组把1只攻击力2000以下的魔法师族怪兽攻击表示特殊召唤。'),
(13758665, 'Magician''s Left Hand', '魔术师的左手', '魔術師の左手', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己场上有魔法师族怪兽存在的场合，对方发动的陷阱卡的效果无效并破坏。'),
(40252269, 'Magician''s Restage', '魔术师的再演', '魔術師の再演', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只在这张卡在场上表侧表示存在才有1次，以自己墓地1只3星以下的魔法师族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡被送去墓地的场合才能发动。从卡组把「魔术师的再演」以外的1张「魔术师」永续魔法卡加入手卡。'),
(87769556, 'Magician''s Right Hand', '魔术师的右手', '魔術師の右手', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己场上有魔法师族怪兽存在的场合，对方发动的魔法卡的效果无效并破坏。'),
(71696014, 'Magician''s Robe', '魔术师之袍', 'マジシャンズ・ローブ', 'Effect Monster', 'Spellcaster', 'DARK', 2, 700, 2000, '「魔术师之袍」的①②的效果1回合各能使用1次。 ①：对方回合从手卡丢弃1张魔法·陷阱卡才能发动。从卡组把1只「黑魔术师」特殊召唤。 ②：这张卡在墓地存在的状态，对方回合自己把魔法·陷阱卡的效果发动的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(7084129, 'Magician''s Rod', '魔术师之杖', 'マジシャンズ・ロッド', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1600, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤时才能发动。把有「黑魔术师」的卡名记述的1张魔法·陷阱卡从卡组加入手卡。 ②：这张卡在墓地存在的状态，自己在对方回合把魔法·陷阱卡的效果发动的场合，把自己场上1只魔法师族怪兽解放才能发动。这张卡加入手卡。'),
(95477924, 'Magician''s Salvation', '魔术师救助', 'マジシャンズ・サルベーション', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1张「永远之魂」在自己场上盖放。 ②：自己把「黑魔术师」或「黑魔术少女」召唤·特殊召唤的场合，以那之内的1只为对象才能发动。和那只怪兽卡名不同的1只「黑魔术师」或「黑魔术少女」从自己墓地特殊召唤。'),
(80304126, 'Magician''s Valkyria', '魔术女武神', 'マジシャンズ・ヴァルキリア', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1800, '①：只要这张卡在怪兽区域存在，对方怪兽不能选择其他的魔法师族怪兽作为攻击对象。'),
(15845914, 'Magicians of Bonds and Unity', '团结与羁绊的魔导师', '結束と絆の魔導師', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2500, '这张卡不能通常召唤。自己墓地有卡25张以上存在的场合才能特殊召唤。 ①：只要对方墓地有卡25张以上存在，这张卡的攻击力·守备力上升2500。'),
(36045450, 'Magicians Unite', '魔术师的合击', 'マジシャンズ・クロス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有攻击表示的魔法师族怪兽2只以上存在的场合，以那之内的1只为对象才能发动。那只怪兽的攻击力直到回合结束时变成3000。这张卡的发动后，直到回合结束时那只怪兽以外的魔法师族怪兽不能攻击。'),
(86509711, 'Magicians'' Combination', '魔术师联手', 'マジシャンズ・コンビネーション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，魔法·陷阱·怪兽的效果发动时，把自己场上1只「黑魔术师」或者「黑魔术少女」解放才能发动。从自己的手卡·墓地选和解放的怪兽卡名不同的1只「黑魔术师」或者「黑魔术少女」特殊召唤，那个发动的效果无效。 ②：魔法与陷阱区域的表侧表示的这张卡被送去墓地的场合才能发动。选场上1张卡破坏。'),
(89448140, 'Magicians'' Defense', '魔术师防护', 'マジシャンズ・プロテクション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要自己场上有魔法师族怪兽存在，自己受到的全部伤害变成一半。 ②：这张卡从场上送去墓地的场合，以自己墓地1只魔法师族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(97631303, 'Magicians'' Souls', '魔术师双魂', 'マジシャンズ・ソウルズ', 'Effect Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，可以从卡组把1只6星以上的魔法师族怪兽送去墓地，从以下效果选择1个发动。 ●这张卡特殊召唤。 ●这张卡送去墓地。那之后，可以从自己墓地把1只「黑魔术师」或「黑魔术少女」特殊召唤。 ②：从自己的手卡·场上把最多2张魔法·陷阱卡送去墓地才能发动。自己抽出送去墓地的数量。'),
(67694706, 'Magicolloidal Sol', '魔溶生物 佐尔', '魔溶生物ゾル', 'Tuner Monster', 'Aqua', 'WATER', 2, 400, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的陷阱卡的效果让怪兽特殊召唤的场合才能发动。这张卡从手卡·墓地特殊召唤。这个效果从墓地特殊召唤的这张卡从场上离开的场合除外。 ②：对方战斗阶段，可以从以下效果选择1个发动。 ●用包含这张卡的自己场上的怪兽为素材进行同调召唤。 ●用包含这张卡的自己场上的怪兽为素材进行超量召唤。'),
(66078354, 'Magicore Warrior of the Relics', '遗迹的魔矿战士', '遺跡の魔鉱戦士', 'Effect Monster', 'Warrior', 'FIRE', 4, 2300, 1000, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有「勇者衍生物」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上没有「勇者衍生物」存在的场合，这张卡不能攻击。 ③：有「勇者衍生物」的衍生物名记述的自己怪兽进行战斗的战斗阶段结束时才能发动。从卡组选有「勇者衍生物」的衍生物名记述的1张陷阱卡在自己的魔法与陷阱区域盖放。');